+                    if (localReleasables.add(trackedSnapshot.tryAcquirePermit()) == null) {
+                        return;
+                    }
+
+                    if (snapshots.get(trackedSnapshot.snapshotName) != trackedSnapshot) {
+                        // concurrently removed
