+                        }
+
+                        getIndicesStep.onResponse(randomSubsetOf(between(1, cloneableIndices.size()), cloneableIndices));
+                    }));
+
+                    getIndicesStep.addListener(mustSucceed(indexNames -> {
+
+                        if (indexNames.isEmpty()) {
