+
+                        final String cloneName = "snapshot-clone-" + snapshotCounter.incrementAndGet();
+
+                        logger.info(
+                            "--> starting clone of [{}:{}] as [{}:{}] with indices {}",
+                            trackedSnapshot.trackedRepository.repositoryName,
+                            trackedSnapshot.snapshotName,
