+    private static String stringFromSnapshotInfo(SnapshotInfo snapshotInfo) {
+        return Strings.toString((b, p) -> snapshotInfo.toXContent(b, SNAPSHOT_ONLY_FORMAT_PARAMS), true, false);
+    }
